'use strict';

// MODULES //

var logger = require( 'debug' );
var trim = require( '@stdlib/string/trim' );


// VARIABLES //

var debug = logger( 'c-doctest:extract' );

// Regular expression to match the start of a JSDoc-style comment:
var RE_COMMENT_START = /\/\*\*/;

// Regular expression to match the end of a JSDoc-style comment:
var RE_COMMENT_END = /\*\//;

// Regular expression to match @example tag:
var RE_EXAMPLE_TAG = /^\s*\*\s*@example\s*$/;

// Regular expression to match a JSDoc tag (any tag other than @example):
var RE_OTHER_TAG = /^\s*\*\s*@(?!example)\w+/;

// Regular expression to match a comment line content (strip leading * ):
var RE_COMMENT_LINE = /^\s*\*\s?(.*)$/;

// Regular expression to match a "// returns" annotation:
var RE_RETURNS = /\/\/\s*returns\s+(.*)/;

// Regular expression to detect approximate returns (prefixed with ~):
var RE_APPROX = /^~(.+)/;


// MAIN //

/**
* Extracts `@example` blocks from C source file content.
*
* @param {string} content - file content
* @param {string} fpath - file path (for debug logging)
* @returns {Array} array of example objects
*
* @example
* var content = '/**\n* @example\n* double y = foo( 1.0 );\n* // returns 2.0\n*\/';
* var examples = extractExamples( content, 'test.c' );
* // returns [ { 'code': 'double y = foo( 1.0 );\n// returns 2.0', 'returns': [ { 'expected': '2.0', 'approximate': false } ], 'line': 2 } ]
*/
function extractExamples( content, fpath ) {
	var examples;
	var lines;
	var i;

	examples = [];
	lines = content.split( '\n' );

	i = 0;
	while ( i < lines.length ) {
		// Look for start of a JSDoc comment:
		if ( RE_COMMENT_START.test( lines[ i ] ) ) {
			i = parseComment( lines, i, examples, fpath );
		} else {
			i += 1;
		}
	}
	return examples;
}

/**
* Parses a JSDoc comment block for `@example` tags.
*
* @private
* @param {StringArray} lines - file lines
* @param {number} startIdx - index of comment start
* @param {Array} examples - accumulator for example objects
* @param {string} fpath - file path (for debug logging)
* @returns {number} index after the comment block
*/
function parseComment( lines, startIdx, examples, fpath ) {
	var inExample;
	var exLines;
	var match;
	var line;
	var i;

	inExample = false;
	exLines = [];

	for ( i = startIdx + 1; i < lines.length; i++ ) {
		line = lines[ i ];

		// Check for end of comment block:
		if ( RE_COMMENT_END.test( line ) ) {
			if ( inExample && exLines.length > 0 ) {
				pushExample( examples, exLines, fpath );
			}
			return i + 1;
		}

		// Check for @example tag:
		if ( RE_EXAMPLE_TAG.test( line ) ) {
			// If we were already in an example, save the previous one:
			if ( inExample && exLines.length > 0 ) {
				pushExample( examples, exLines, fpath );
			}
			inExample = true;
			exLines = [];
			exLines.startLine = i + 1; // 1-indexed line number
			continue;
		}

		// Check for another JSDoc tag (ends the current @example block):
		if ( RE_OTHER_TAG.test( line ) ) {
			if ( inExample && exLines.length > 0 ) {
				pushExample( examples, exLines, fpath );
			}
			inExample = false;
			exLines = [];
			continue;
		}

		// If inside an @example block, collect lines:
		if ( inExample ) {
			match = RE_COMMENT_LINE.exec( line );
			if ( match ) {
				exLines.push( match[ 1 ] );
			}
		}
	}

	// If file ended without closing comment (shouldn't happen normally):
	if ( inExample && exLines.length > 0 ) {
		pushExample( examples, exLines, fpath );
	}
	return i;
}

/**
* Creates an example object from collected lines and pushes to accumulator.
*
* @private
* @param {Array} examples - accumulator
* @param {Array} exLines - collected example lines (with `startLine` property)
* @param {string} fpath - file path
*/
function pushExample( examples, exLines, fpath ) {
	var assertions;
	var approx;
	var match;
	var code;
	var val;
	var i;

	assertions = [];

	// Parse return annotations:
	for ( i = 0; i < exLines.length; i++ ) {
		match = RE_RETURNS.exec( exLines[ i ] );
		if ( match ) {
			val = trim( match[ 1 ] );
			approx = RE_APPROX.exec( val );
			if ( approx ) {
				assertions.push({
					'expected': trim( approx[ 1 ] ),
					'approximate': true,
					'lineOffset': i
				});
			} else {
				assertions.push({
					'expected': val,
					'approximate': false,
					'lineOffset': i
				});
			}
		}
	}

	// Filter out blank-only examples:
	code = trim( exLines.join( '\n' ) );
	if ( code.length === 0 ) {
		debug( 'Skipping empty @example block at line %d in %s.', exLines.startLine, fpath );
		return;
	}
	// Filter out illustrative examples containing ellipsis placeholders (e.g., `foo( ... )`).
	// These are architectural/documentation examples that show usage patterns, not runnable code:
	if ( /\.\.\./g.test( code ) ) {
		debug( 'Skipping illustrative @example block (contains ellipsis) at line %d in %s.', exLines.startLine, fpath );
		return;
	}
	debug( 'Found @example block at line %d in %s with %d assertion(s).', exLines.startLine, fpath, assertions.length );

	examples.push({
		'code': code,
		'assertions': assertions,
		'line': exLines.startLine
	});
}


// EXPORTS //

module.exports = extractExamples;
